class Solution {
public:
    long long maxArea(int height, vector<int>& positions, string directions) {
        long long area = 0;
        for (int p : positions) area += p;
        long long ans = area;
        long long diff = 0;

        map<int, vector<int>> events;
        for (int i = 0; i < positions.size(); ++i) {
            if (directions[i] == 'U') {
                events[height - positions[i]].push_back(i);
                events[height - positions[i] + height].push_back(i);
                diff++;
            } else {
                events[positions[i]].push_back(i);
                events[positions[i] + height].push_back(i);
                diff--;
            }
        }

        int prev_time = 0;
        for (const auto& [t, indices] : events) {
            area += 1LL * (t - prev_time) * diff;
            ans = max(ans, area);
            prev_time = t;
            for (int idx : indices) {
                if (directions[idx] == 'U') {
                    directions[idx] = 'D';
                    diff -= 2;
                } else {
                    directions[idx] = 'U';
                    diff += 2;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public long maxArea(int height, int[] positions, String directions) {
        long area = 0;
        for (int p : positions) area += p;
        long ans = area;
        long diff = 0;

        TreeMap<Integer, List<Integer>> events = new TreeMap<>();
        char[] dirs = directions.toCharArray();
        for (int i = 0; i < positions.length; ++i) {
            if (dirs[i] == 'U') {
                events.computeIfAbsent(height - positions[i], k -> new ArrayList<>()).add(i);
                events.computeIfAbsent(height - positions[i] + height, k -> new ArrayList<>()).add(i);
                diff++;
            } else {
                events.computeIfAbsent(positions[i], k -> new ArrayList<>()).add(i);
                events.computeIfAbsent(positions[i] + height, k -> new ArrayList<>()).add(i);
                diff--;
            }
        }

        int prevTime = 0;
        for (Map.Entry<Integer, List<Integer>> entry : events.entrySet()) {
            int t = entry.getKey();
            area += (long) (t - prevTime) * diff;
            ans = Math.max(ans, area);
            prevTime = t;
            for (int idx : entry.getValue()) {
                if (dirs[idx] == 'U') {
                    dirs[idx] = 'D';
                    diff -= 2;
                } else {
                    dirs[idx] = 'U';
                    diff += 2;
                }
            }
        }
        return ans;
    }
}

var maxArea = function(height, positions, directions) {
    let area = BigInt(positions.reduce((a, b) => a + b, 0));
    let ans = area;
    let diff = 0n;

    const events = new Map();
    const dirs = directions.split('');

    for (let i = 0; i < positions.length; i++) {
        if (dirs[i] === 'U') {
            const t1 = height - positions[i];
            const t2 = height - positions[i] + height;
            if (!events.has(t1)) events.set(t1, []);
            if (!events.has(t2)) events.set(t2, []);
            events.get(t1).push(i);
            events.get(t2).push(i);
            diff += 1n;
        } else {
            const t1 = positions[i];
            const t2 = positions[i] + height;
            if (!events.has(t1)) events.set(t1, []);
            if (!events.has(t2)) events.set(t2, []);
            events.get(t1).push(i);
            events.get(t2).push(i);
            diff -= 1n;
        }
    }

    const sortedTimes = Array.from(events.keys()).sort((a, b) => a - b);
    let prevTime = 0;
    for (const t of sortedTimes) {
        area += BigInt(t - prevTime) * diff;
        if (area > ans) ans = area;
        prevTime = t;
        for (const idx of events.get(t)) {
            if (dirs[idx] === 'U') {
                dirs[idx] = 'D';
                diff -= 2n;
            } else {
                dirs[idx] = 'U';
                diff += 2n;
            }
        }
    }
    return Number(ans);
};
